def build(Qs, stem, kind, name, title, note, idp):
    bad = []; rows = []; mq = []; ma = []
    for i, (topic, kk) in enumerate(Qs, 1):
        assert len(kk) == 4 and sum(k[1] for k in kk) == 1, f"{idp}-{i:02d}: 正しい肢が1つでない"
        ans = [j for j, k in enumerate(kk, 1) if k[1]][0]; cites = []; quotes = []
        for j, (t_, tf, ex, refs) in enumerate(kk, 1):
            assert refs, f"{idp}-{i:02d}-{j}: 根拠なし"
            for r in refs:
                if kind == "m":
                    art, p, q = r; ok = q in m_para(art, p); c = m_cite(art, p)
                else:
                    sec, lab, q = r; ok = q in SEC[sec]; c = k_cite(sec, lab)
                if not ok: bad.append((f"{idp}-{i:02d}-{j}", c, q[:40]))
                cites.append(f"肢{j}:{c}"); quotes.append(f"肢{j}:「{q}」")
        rows.append([f"{idp}-{i:02d}", topic, stem] + [k[0] for k in kk] + [ans, " / ".join(f"肢{j}={'正' if k[1] else '誤'}:{k[2]}" for j, k in enumerate(kk, 1)), " ; ".join(cites), " ; ".join(quotes), "原文一致"])
        mq.append(f"### 問{i}({idp}-{i:02d} / 論点{topic})\n\n{stem}\n\n" + "\n".join(f"{j}. {k[0]}" for j, k in enumerate(kk, 1)) + "\n")
        ma.append(f"### 問{i} 正解:{ans}\n\n" + "\n".join(f"- 肢{j}【{'正' if k[1] else '誤'}】{k[2]} 〔根拠:{'、'.join(dict.fromkeys((m_cite(r[0], r[1]) if kind == 'm' else k_cite(r[0], r[1])) for r in k[3]))}〕" for j, k in enumerate(kk, 1)) + "\n")
    if bad:
        for b in bad: print("不一致:", b)
        raise SystemExit(f"{name}: 原文に見つからない引用 {len(bad)} 件。出力しない")
    with open(f"06_練習問題/練習問題_{name}.csv", "w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f); w.writerow(["問題ID", "論点ID", "問題文", "肢1", "肢2", "肢3", "肢4", "正解", "解説(肢別)", "根拠", "根拠原文(抜粋)", "検証"]); w.writerows(rows)
    open(f"06_練習問題/練習問題_{name}.md", "w", encoding="utf-8").write(f"# 練習問題:{title}(全{len(Qs)}問)\n\n- 作成:AI(Sonnet)。**本試験の過去問ではなく、練習用の創作問題**。\n{note}\n- 限界:問題の切り口・難易度は本試験と異なる。肢の言い換えの妥当性は人の確認を推奨。\n\n## 問題\n\n" + "\n".join(mq) + "\n---\n\n## 正解と解説\n\n" + "\n".join(ma))
    print(name, "問題数", len(Qs), "検証済み引用", sum(len(k[3]) for _, kk in Qs for k in kk), "正解位置", dict(sorted(Counter(r[7] for r in rows).items())))
build(M, SM, "m", "民法", "民法(意思表示・代理・時効・債権・不法行為)", "- 根拠:e-Gov法令検索の民法(2026-10-01取得、`01_原本/法令データ/民法_egov.xml`)。全肢の根拠条・項と原文の一部を原文と照合済み(`scripts/make_practice_questions_mn04_sb03.py`)。\n- 注意:令和6年の民法改正(親権等)は使っていない。出題基準日は令和8年4月1日施行の法令。", "PM")
